4	const runCli = (stdin: string): Promise<string> =>
5	  new Promise((resolve, reject) => {
6	    const cli = spawn("npx", ["tsx", "src/cli.ts"], { stdio: "pipe" });
7	    let stdout = "";
8	    let stderr = "";
9	    cli.stdout.on("data", (chunk) => (stdout += chunk));
10	    cli.stderr.on("data", (chunk) => (stderr += chunk));
11	    cli.on("error", reject);
12	    cli.on("close", (code) =>
13	      code === 0 ? resolve(stdout) : reject(new Error(`exit ${code}: ${stderr}`)),
14	    );
15	    cli.stdin.end(stdin);
16	  });
17	
18	describe("Sphinx scoring CLI", () => {
